.stage {
  --bg: #05060a; --ink: #f4f6fb; --muted: #8b93a7; --accent: #3de0ff; --accent-soft: #8b7bff; --surface: rgba(255, 255, 255, 0.06);
  --warm: #ffb86b; --good: #5ef0a8;
  position: absolute; inset: 0; overflow: hidden; background: var(--bg); color: var(--ink); font-family: "Inter", sans-serif;
}
* { margin: 0; padding: 0; }
/* ---------- shared ---------- */
.scene { position: absolute; inset: 0; opacity: 0; perspective: 2400px; }
.center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.clip { display: block; overflow: hidden; padding: 0.04em 0.06em 0.16em; margin: -0.04em -0.06em -0.16em; }
.clip > i { display: block; font-style: normal; animation: rise 1.05s cubic-bezier(0.16, 1, 0.3, 1) 0s both; }
.grad {
  background: linear-gradient(100deg, var(--accent), var(--accent-soft) 58%, var(--warm));
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.kicker { display: flex; align-items: center; gap: 18px; margin-bottom: 36px; font-family: "Roboto Mono", monospace; font-weight: 700; font-size: 26px; letter-spacing: 0.22em; color: var(--accent); }
.kicker span { color: var(--ink); opacity: 0.45; }
.col { position: absolute; left: 130px; top: 0; bottom: 0; width: 860px; display: flex; flex-direction: column; justify-content: center; }
.lede { margin-top: 40px; font-size: 38px; line-height: 1.45; color: var(--muted); max-width: 700px; }
.chip { font-family: "Roboto Mono", monospace; font-weight: 700; font-size: 21px; letter-spacing: 0.06em; padding: 10px 20px; border-radius: 999px; border: 1px solid currentColor; background: rgba(255, 255, 255, 0.05); white-space: nowrap; }
.chip.cyan { color: var(--accent); }
.chip.green { color: var(--good); }
.chip.amber { color: var(--warm); }

.s1 { opacity: 1; animation: scene-out 0.6s cubic-bezier(0.64, 0, 0.78, 0) 3.5s forwards; }
.s2 { animation: scene-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) 3.7s both, scene-out 0.6s cubic-bezier(0.64, 0, 0.78, 0) 7.6s forwards; }
.s3 { animation: scene-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) 7.8s both, scene-out 0.6s cubic-bezier(0.64, 0, 0.78, 0) 11s forwards; }
.s4 { animation: scene-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) 11.2s both; }

/* ---------- background ---------- */
.bg { position: absolute; inset: 0; overflow: hidden; }
.grid {
  position: absolute; inset: -2px;
  background-image: linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 96px 96px;
  -webkit-mask-image: radial-gradient(ellipse 72% 62% at 50% 50%, #000 15%, transparent 78%);
  mask-image: radial-gradient(ellipse 72% 62% at 50% 50%, #000 15%, transparent 78%);
  animation: grid-in 1.8s cubic-bezier(0.25, 1, 0.5, 1) 0s both;
}
.orb { position: absolute; border-radius: 50%; filter: blur(120px); }
.orb.a { width: 980px; height: 980px; left: -260px; top: -380px; background: radial-gradient(circle, rgba(32, 110, 255, 0.55), rgba(32, 110, 255, 0) 66%); animation: drift-a 7s cubic-bezier(0.45, 0, 0.55, 1) 0s infinite alternate; }
.orb.b { width: 900px; height: 900px; right: -280px; bottom: -420px; background: radial-gradient(circle, rgba(139, 123, 255, 0.5), rgba(139, 123, 255, 0) 66%); animation: drift-b 7s cubic-bezier(0.45, 0, 0.55, 1) 0s infinite alternate; }
.orb.c { width: 1000px; height: 520px; left: 460px; bottom: -330px; background: radial-gradient(ellipse, rgba(255, 184, 107, 0.4), rgba(255, 184, 107, 0) 68%); animation: glow-in 1.6s cubic-bezier(0.25, 1, 0.5, 1) 11s both; }
.vig { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse 85% 75% at 50% 50%, transparent 55%, rgba(0, 0, 0, 0.62) 100%); }

/* ---------- scene 1: hook ---------- */
.eyebrow { display: inline-flex; align-items: center; gap: 16px; padding: 14px 28px; margin-bottom: 52px; border-radius: 999px; border: 1px solid rgba(255, 255, 255, 0.15); background: rgba(255, 255, 255, 0.05); font-family: "Roboto Mono", monospace; font-weight: 700; font-size: 25px; letter-spacing: 0.18em; color: #cdd5e6; animation: eyebrow 1s cubic-bezier(0.16, 1, 0.3, 1) 0.2s both; }
.dot { position: relative; width: 14px; height: 14px; border-radius: 50%; background: var(--accent); }
.dot::after { content: ""; position: absolute; inset: 0; border-radius: 50%; border: 2px solid var(--accent); animation: ping 1.8s cubic-bezier(0, 0, 0.2, 1) 0.2s infinite; }
.hero { font-size: 196px; line-height: 0.96; font-weight: 900; letter-spacing: -0.045em; }
.line { display: block; }
.w { display: inline-block; overflow: hidden; vertical-align: top; padding: 0.05em 0.05em 0.16em; margin: -0.05em -0.05em -0.16em; }
.w > i { display: block; font-style: normal; animation: rise 1.05s cubic-bezier(0.16, 1, 0.3, 1) 0s both; }
.w.d1 > i { animation-delay: 0.55s; }
.w.d2 > i { animation-delay: 0.7s; }
.w.d3 > i { animation-delay: 0.85s; }
.w.hl > i {
  background: linear-gradient(100deg, var(--accent) 0%, var(--accent-soft) 40%, var(--warm) 70%, var(--accent) 100%);
  background-size: 230% 100%;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  animation: rise 1.15s cubic-bezier(0.16, 1, 0.3, 1) 1.05s both, shine 2.2s cubic-bezier(0.45, 0, 0.55, 1) 1.6s both;
}
.sub { margin-top: 46px; max-width: 1120px; font-size: 40px; line-height: 1.4; color: var(--muted); animation: fade-up 0.9s cubic-bezier(0.25, 1, 0.5, 1) 1.75s both; }

/* ---------- scene 2: board ---------- */
.k2 { animation: fade-up 0.8s cubic-bezier(0.25, 1, 0.5, 1) 4.1s both; }
.h2 { font-size: 148px; line-height: 0.98; font-weight: 900; letter-spacing: -0.04em; }
.c1 > i { animation-delay: 4.25s; }
.c2 > i { animation-delay: 4.4s; }
.c3 > i { animation-delay: 4.55s; }
.l2 { animation: fade-up 0.9s cubic-bezier(0.25, 1, 0.5, 1) 4.9s both; }
.glow { position: absolute; border-radius: 50%; filter: blur(90px); }
.g1 { width: 560px; height: 560px; left: 1420px; top: 60px; background: radial-gradient(circle, rgba(61, 224, 255, 0.6), rgba(61, 224, 255, 0) 70%); animation: glow-in 1.4s cubic-bezier(0.25, 1, 0.5, 1) 4s both, float-a 6s cubic-bezier(0.45, 0, 0.55, 1) 4s infinite alternate; }
.g2 { width: 520px; height: 520px; left: 880px; top: 560px; background: radial-gradient(circle, rgba(139, 123, 255, 0.6), rgba(139, 123, 255, 0) 70%); animation: glow-in 1.4s cubic-bezier(0.25, 1, 0.5, 1) 4.2s both, float-b 6s cubic-bezier(0.45, 0, 0.55, 1) 4s infinite alternate; }
.card {
  position: absolute; left: 1020px; top: 150px; width: 760px; height: 780px; padding: 52px; overflow: hidden;
  border-radius: 44px; transform-origin: 50% 100%;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.17), rgba(255, 255, 255, 0.05) 55%, rgba(255, 255, 255, 0.09));
  border: 1px solid rgba(255, 255, 255, 0.2);
  -webkit-backdrop-filter: blur(36px) saturate(170%); backdrop-filter: blur(36px) saturate(170%);
  box-shadow: 0 70px 140px -40px rgba(0, 0, 0, 0.75), 0 0 0 1px rgba(255, 255, 255, 0.04), inset 0 1.5px 0 rgba(255, 255, 255, 0.3);
  animation: card-in 1.2s cubic-bezier(0.16, 1, 0.3, 1) 4.3s both;
}
.sheen { position: absolute; inset: 0; pointer-events: none; background: linear-gradient(115deg, transparent 36%, rgba(255, 255, 255, 0.22) 50%, transparent 64%); transform: translateX(-130%); animation: sheen 1.7s cubic-bezier(0.45, 0, 0.55, 1) 5.6s forwards; }
.card-head { display: flex; align-items: center; justify-content: space-between; animation: fade-up 0.8s cubic-bezier(0.25, 1, 0.5, 1) 4.7s both; }
.card-head b { font-size: 46px; font-weight: 700; letter-spacing: -0.02em; }
.meter { margin: 34px 0 30px; }
.meter-track { height: 12px; border-radius: 6px; background: rgba(255, 255, 255, 0.1); overflow: hidden; }
.meter-track i { display: block; width: 82%; height: 100%; border-radius: 6px; background: linear-gradient(90deg, var(--accent), var(--accent-soft)); transform-origin: 0 50%; animation: fill 1.6s cubic-bezier(0.65, 0, 0.35, 1) 5s both; }
.meter-label { display: block; margin-top: 16px; font-family: "Roboto Mono", monospace; font-weight: 700; font-size: 21px; letter-spacing: 0.16em; color: var(--muted); animation: fade-up 0.8s cubic-bezier(0.25, 1, 0.5, 1) 5.3s both; }
.rows { list-style: none; display: grid; gap: 16px; }
.row { display: flex; align-items: center; gap: 22px; height: 104px; padding: 0 28px; border-radius: 26px; background: var(--surface); border: 1px solid rgba(255, 255, 255, 0.08); animation: row-in 0.9s cubic-bezier(0.16, 1, 0.3, 1) both; }
.r1 { animation-delay: 5s; }
.r2 { animation-delay: 5.15s; }
.r3 { animation-delay: 5.3s; }
.r4 { animation-delay: 5.45s; }
.name { flex: 1; font-size: 33px; font-weight: 700; letter-spacing: -0.015em; }
.tick { width: 48px; height: 48px; flex: none; fill: none; stroke-width: 3.5; stroke-linecap: round; stroke-linejoin: round; overflow: visible; }
.tick circle:first-child { stroke: rgba(255, 255, 255, 0.34); stroke-dasharray: 1 2; stroke-dashoffset: 1; animation: draw 0.8s cubic-bezier(0.65, 0, 0.35, 1) both; }
.r1 .tick circle { animation-delay: 5.3s; }
.r2 .tick circle { animation-delay: 5.45s; }
.r3 .tick circle { animation-delay: 5.6s; }
.r4 .tick circle { animation-delay: 5.75s; }
.tick.done circle:first-child { stroke: var(--good); }
.tick.done path { stroke: var(--good); stroke-dasharray: 1 2; stroke-dashoffset: 1; animation: draw 0.5s cubic-bezier(0.65, 0, 0.35, 1) 5.95s both; }
.tick .pulse { fill: var(--accent); stroke: none; transform-box: fill-box; transform-origin: center; animation: beat 1.4s cubic-bezier(0.45, 0, 0.55, 1) 6s infinite alternate both; }

/* ---------- scene 3: momentum ---------- */
.col.wide { width: 780px; }
.k3 { animation: fade-up 0.8s cubic-bezier(0.25, 1, 0.5, 1) 8.2s both; }
.stat { font-size: 310px; line-height: 0.95; font-weight: 900; letter-spacing: -0.065em; }
.stat .clip > i { animation-delay: 8.35s; animation-duration: 1.2s; }
.l3 { margin-top: 28px; font-size: 46px; animation: fade-up 0.9s cubic-bezier(0.25, 1, 0.5, 1) 9s both; }
.chart { position: absolute; left: 960px; top: 250px; width: 840px; height: 523px; overflow: visible; }
.gl line { stroke: rgba(255, 255, 255, 0.1); stroke-width: 2; stroke-dasharray: 1 2; stroke-dashoffset: 1; animation: draw 1.1s cubic-bezier(0.25, 1, 0.5, 1) both; }
.gl line:nth-child(1) { animation-delay: 8.5s; }
.gl line:nth-child(2) { animation-delay: 8.58s; }
.gl line:nth-child(3) { animation-delay: 8.66s; }
.gl line:nth-child(4) { animation-delay: 8.74s; }
.gl line.base { stroke: rgba(255, 255, 255, 0.3); animation-delay: 8.3s; }
.area { fill: url(#ar); clip-path: inset(0 100% 0 0); animation: wipe 1.7s cubic-bezier(0.65, 0, 0.35, 1) 8.7s both; }
.ln { fill: none; stroke: url(#ln); stroke-width: 9; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1 2; stroke-dashoffset: 1; animation: draw 1.7s cubic-bezier(0.65, 0, 0.35, 1) 8.7s both; }
.node { fill: #05060a; stroke: #fff; stroke-width: 5; transform-box: fill-box; transform-origin: center; animation: pop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) both; }
.n1 { animation-delay: 9.3s; }
.n2 { animation-delay: 9.55s; }
.n3 { animation-delay: 9.78s; }
.n4 { stroke: var(--warm); animation-delay: 10.3s; }
.ring { fill: none; stroke: var(--warm); stroke-width: 3; transform-box: fill-box; transform-origin: center; animation: ping-ring 1.8s cubic-bezier(0, 0, 0.2, 1) 10.4s infinite both; }
.ax { font-family: "Roboto Mono", monospace; font-weight: 700; font-size: 22px; letter-spacing: 0.16em; fill: var(--muted); animation: fade-up 0.8s cubic-bezier(0.25, 1, 0.5, 1) both; }
.x1 { animation-delay: 8.9s; }
.x2 { animation-delay: 9s; }
.x3 { animation-delay: 9.1s; }

/* ---------- scene 4: end card ---------- */
.mark { width: 210px; height: 210px; margin-bottom: 36px; fill: none; stroke-linecap: round; stroke-width: 6; overflow: visible; }
.mark circle { stroke: url(#mk); stroke-dasharray: 1 2; stroke-dashoffset: 1; transform-box: fill-box; transform-origin: center; transform: rotate(-90deg); animation: draw 1.3s cubic-bezier(0.65, 0, 0.35, 1) 11.5s both; }
.mark path { stroke: #fff; stroke-width: 7; stroke-dasharray: 1 2; stroke-dashoffset: 1; animation: draw 0.9s cubic-bezier(0.65, 0, 0.35, 1) 12s both; }
.word { font-size: 180px; line-height: 1; font-weight: 900; letter-spacing: -0.05em; }
.word .clip > i { animation-delay: 12.3s; }
.tag { margin-top: 18px; font-size: 44px; color: var(--muted); animation: fade-up 0.9s cubic-bezier(0.25, 1, 0.5, 1) 12.75s both; }
.cta { display: inline-flex; align-items: center; gap: 26px; margin-top: 62px; padding: 26px 46px; border-radius: 999px; background: linear-gradient(100deg, var(--accent), var(--accent-soft)); color: #05060a; font-size: 40px; font-weight: 700; animation: cta-in 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) 13s both, cta-glow 1.8s cubic-bezier(0.45, 0, 0.55, 1) 13s infinite alternate; }
.cta .sep { width: 2px; height: 36px; background: rgba(5, 6, 10, 0.3); }
.cta b { font-family: "Roboto Mono", monospace; font-weight: 700; font-size: 28px; letter-spacing: 0.04em; opacity: 0.75; }

/* ---------- keyframes ---------- */
@keyframes rise { from { transform: translateY(112%) rotate(3deg); } to { transform: none; } }
@keyframes fade-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: none; } }
@keyframes eyebrow { from { opacity: 0; letter-spacing: 0.7em; transform: translateY(18px); } to { opacity: 1; letter-spacing: 0.18em; transform: none; } }
@keyframes shine { from { background-position: 100% 0; } to { background-position: 0% 0; } }
@keyframes ping { 0% { transform: scale(1); opacity: 0.9; } 80%, 100% { transform: scale(3.2); opacity: 0; } }
@keyframes scene-in { from { opacity: 0; transform: scale(1.04); } to { opacity: 1; transform: none; } }
@keyframes scene-out { from { opacity: 1; transform: none; filter: blur(0); } to { opacity: 0; transform: translateY(-24px) scale(0.97); filter: blur(14px); } }
@keyframes grid-in { from { opacity: 0; transform: scale(1.1); } to { opacity: 1; transform: none; } }
@keyframes drift-a { from { transform: translate(0, 0) scale(1); } to { transform: translate(300px, 200px) scale(1.15); } }
@keyframes drift-b { from { transform: translate(0, 0) scale(1); } to { transform: translate(-320px, -170px) scale(1.2); } }
@keyframes glow-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes float-a { from { transform: translate(0, 0); } to { transform: translate(-60px, 90px); } }
@keyframes float-b { from { transform: translate(0, 0); } to { transform: translate(80px, -70px); } }
@keyframes card-in { from { opacity: 0; transform: translateY(110px) rotateX(16deg) scale(0.93); } to { opacity: 1; transform: none; } }
@keyframes sheen { from { transform: translateX(-130%); } to { transform: translateX(130%); } }
@keyframes fill { from { transform: scaleX(0); } to { transform: none; } }
@keyframes row-in { from { opacity: 0; transform: translateX(70px); filter: blur(8px); } to { opacity: 1; transform: none; filter: blur(0); } }
@keyframes draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes beat { from { transform: scale(0.7); opacity: 0.7; } to { transform: scale(1.15); opacity: 1; } }
@keyframes wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes pop { from { transform: scale(0); } to { transform: scale(1); } }
@keyframes ping-ring { 0% { transform: scale(0.8); opacity: 0; } 15% { opacity: 0.9; } 100% { transform: scale(2.6); opacity: 0; } }
@keyframes cta-in { from { opacity: 0; transform: translateY(40px) scale(0.9); } to { opacity: 1; transform: none; } }
@keyframes cta-glow { from { box-shadow: 0 0 0 0 rgba(61, 224, 255, 0), 0 20px 60px -20px rgba(61, 224, 255, 0.35); } to { box-shadow: 0 0 0 18px rgba(61, 224, 255, 0.1), 0 30px 90px -10px rgba(139, 123, 255, 0.6); } }
